import React, { useEffect, useState } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import api from '../services/api';
import ProductCard from '../components/ProductCard';
import PageBanner from '../components/PageBanner';

const Shop = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [data, setData] = useState({ products: [], categories: [], totalPages: 1, page: 0 });
  const [loading, setLoading] = useState(true);

  const filter = searchParams.get('filter') || '';
  const sort = searchParams.get('sort') || 'newest';
  const category = searchParams.get('category') || '';
  const page = parseInt(searchParams.get('page') || '0', 10);

  useEffect(() => {
    setLoading(true);
    api.get('/products', { params: { filter, sort, category: category || undefined, page, size: 12 } })
      .then(res => { setData(res.data); setLoading(false); })
      .catch(() => setLoading(false));
  }, [filter, sort, category, page]);

  const getTitle = () => {
    if (filter === 'featured') return 'Featured Products';
    if (filter === 'newest' || filter === 'new') return 'New Arrivals';
    if (filter === 'best') return 'Best Sellers';
    if (filter === 'sale') return 'Sale Items';
    return 'All Products';
  };

  const updateSort = (val) => {
    const p = new URLSearchParams(searchParams);
    p.set('sort', val);
    p.set('page', '0');
    setSearchParams(p);
  };

  const changePage = (p) => {
    const sp = new URLSearchParams(searchParams);
    sp.set('page', String(p));
    setSearchParams(sp);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <>
      <PageBanner title={getTitle()} items={[{ label: 'Home', to: '/' }, { label: 'Shop' }]} />

      <section className="section">
        <div className="container">
          <div className="row">
            <div className="col-lg-3 col-md-4">
              <aside className="shop-sidebar">
                <div className="filter-card">
                  <h6>Categories</h6>
                  <div className="form-check mb-2">
                    <input className="form-check-input" type="radio" name="cat" id="catAll" checked={!category} onChange={() => { const p = new URLSearchParams(searchParams); p.delete('category'); p.set('page', '0'); setSearchParams(p); }} />
                    <label className="form-check-label" htmlFor="catAll">All Categories</label>
                  </div>
                  {(data.categories || []).map(cat => (
                    <div className="form-check mb-2" key={cat.id}>
                      <input className="form-check-input" type="radio" name="cat" id={`cat${cat.id}`} checked={category === String(cat.id)} onChange={() => { const p = new URLSearchParams(searchParams); p.set('category', cat.id); p.set('page', '0'); setSearchParams(p); }} />
                      <label className="form-check-label d-flex justify-content-between" htmlFor={`cat${cat.id}`}>
                        <span>{cat.name}</span>
                        {cat.productCount > 0 && <span className="text-muted small">({cat.productCount})</span>}
                      </label>
                    </div>
                  ))}
                </div>
                <div className="filter-card">
                  <h6>Quick Filters</h6>
                  <ul className="list-unstyled mb-0">
                    <li className="mb-2"><Link to="/shop?filter=featured"><i className="bi bi-gem me-2"></i>Featured</Link></li>
                    <li className="mb-2"><Link to="/shop?filter=newest"><i className="bi bi-stars me-2"></i>New Arrivals</Link></li>
                    <li className="mb-2"><Link to="/shop?filter=best"><i className="bi bi-trophy me-2"></i>Best Sellers</Link></li>
                    <li><Link to="/shop?filter=sale"><i className="bi bi-tags me-2"></i>On Sale</Link></li>
                  </ul>
                </div>
              </aside>
            </div>
            <div className="col-lg-9 col-md-8">
              <div className="d-flex justify-content-between align-items-center flex-wrap gap-2 mb-4">
                <div>
                  <h5 className="mb-0">{getTitle()}</h5>
                  <small className="text-muted">{(data.products || []).length} product(s) found</small>
                </div>
                <div className="sort-dropdown d-flex align-items-center gap-2">
                  <label className="small text-muted text-uppercase mb-0">Sort:</label>
                  <select className="form-select" style={{width:'auto'}} value={sort} onChange={(e) => updateSort(e.target.value)}>
                    <option value="newest">Newest</option>
                    <option value="popular">Popular</option>
                    <option value="price_asc">Price: Low to High</option>
                    <option value="price_desc">Price: High to Low</option>
                    <option value="name">Name A-Z</option>
                  </select>
                </div>
              </div>

              {loading ? <p>Loading...</p> : (data.products || []).length === 0 ? (
                <div className="empty-state">
                  <i className="bi bi-box-seam"></i>
                  <h4>No products found</h4>
                  <p className="text-muted">Try adjusting your filters or browse all products.</p>
                  <Link to="/shop" className="btn-gold">Clear Filters</Link>
                </div>
              ) : (
                <>
                  <div className="row">
                    {(data.products || []).map(p => <ProductCard key={p.id} product={p} />)}
                  </div>
                  {data.totalPages > 1 && (
                    <nav aria-label="Pagination"><ul className="pagination justify-content-center">
                      <li className={`page-item ${page <= 0 ? 'disabled' : ''}`}><button className="page-link" onClick={() => changePage(page - 1)} disabled={page <= 0}>&laquo;</button></li>
                      {[...Array(data.totalPages)].map((_, i) => (
                        <li className={`page-item ${i === page ? 'active' : ''}`} key={i}><button className="page-link" onClick={() => changePage(i)}>{i + 1}</button></li>
                      ))}
                      <li className={`page-item ${page >= data.totalPages - 1 ? 'disabled' : ''}`}><button className="page-link" onClick={() => changePage(page + 1)} disabled={page >= data.totalPages - 1}>&raquo;</button></li>
                    </ul></nav>
                  )}
                </>
              )}
            </div>
          </div>
        </div>
      </section>
    </>
  );
};

export default Shop;
